text:
/* Current question code: one pink pill on the activity's top line. */
.question-code-line.question-code-line,.revision-code-line{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.header-question-code.header-question-code{display:inline-flex;align-items:center;min-height:28px;padding:4px 10px;border:1px solid rgba(255,94,203,.46);border-radius:999px;background:rgba(255,94,203,.1);color:#ff5ecb;font:700 11px/1.3 Comfortaa,sans-serif;letter-spacing:.08em;white-space:nowrap}
.header-question-code[hidden]{display:none!important}
html.question-code-header body .review-id.review-id,html.question-code-header body .question-review-id.question-review-id,html.question-code-header body #printedReviewId{display:none!important}
html.question-code-header body .question-review:has(form[hidden]){display:none!important}
.revision-code-line{display:none;font:700 11px Comfortaa,sans-serif;color:#54f5b5;letter-spacing:.08em;margin-bottom:6px}
.test-revising .revision-code-line{display:flex}

.brand-mark img{width:31px;height:40px;object-fit:contain}
.brand-title{min-width:0}.wordmark{display:block;font-size:24px;letter-spacing:-.7px;line-height:1.4}.wordmark span{color:var(--cyan)}
.subject{margin:5px 0 0;font-size:11px;line-height:1.6}.eyebrow{color:var(--accent);letter-spacing:.16em;margin-bottom:6px}
.question-number{color:var(--cyan);border:1px solid #55f6ff47;border-radius:999px;padding:8px 12px;background:#55f6ff0e}.question-number span{color:var(--muted)}
.tool{border:1px solid transparent}.tool[aria-pressed=true]{border-color:#55f6ff66;background:#55f6ff18;color:var(--cyan)}
.view-switch{background:#080c2466}.canvas-wrap{background:#06091d66}
.empty-state,.empty-state p{color:var(--muted)}.start-mark{color:var(--cyan);border-color:#55f6ff66;background:#55f6ff09}
.canvas-footer{border-top:1px solid var(--line)}.next-button,.after-check .text-button{color:var(--cyan)}
.answer{border:1px solid var(--line);border-radius:20px;padding:20px;background:linear-gradient(145deg,#161a44,#0a0d26);gap:12px}
.answer img{background:white;border-radius:12px;padding:8px}.answer-note{margin-bottom:0}
.ghost{opacity:.65}.preview-end{fill:var(--cyan)}.preview-target{stroke:var(--cyan)}
